package main

import (
	"context"
	"fmt"
	"time"
)

// fanIn 从 a、b 两路输入合并到 out。任一路 close 后把对应 case 置 nil 以禁用分支，
// 直到两路都结束才退出；同时支持 ctx 取消和 300ms 软超时心跳。
func fanIn(ctx context.Context, a, b <-chan int, out chan<- int) {
	defer close(out) // 唯一发送方，自己关 out
	for a != nil || b != nil {
		select {
		case v, ok := <-a:
			if !ok { // a 关闭后读到零值+ok=false，把 a 设 nil
				a = nil // select 该 case 永久阻塞 = 等价禁用
				continue
			}
			out <- v
		case v, ok := <-b:
			if !ok {
				b = nil
				continue
			}
			out <- v
		case <-ctx.Done(): // 上游取消：直接退出，out 在 defer 中关闭
			return
		case <-time.After(300 * time.Millisecond):
			fmt.Println("idle 300ms") // 心跳；注意 time.After 会泄露 timer，热路径用 time.NewTimer + Stop
		}
	}
}
